-- Public website content and submission contracts. Additive migration.
CREATE TYPE "PublicCourseCategory" AS ENUM ('ENGLISH', 'EXAM', 'LANGUAGE');
CREATE TYPE "PublicCourseAccent" AS ENUM ('BLUE', 'TURQUOISE', 'YELLOW');
CREATE TYPE "PublicCourseContentKind" AS ENUM ('OVERVIEW', 'HIGHLIGHT', 'OUTCOME', 'CURRICULUM');
CREATE TYPE "PublicEventTimelineStatus" AS ENUM ('UPCOMING', 'PAST');

ALTER TABLE "public_courses" ADD COLUMN "category" "PublicCourseCategory" NOT NULL DEFAULT 'ENGLISH', ADD COLUMN "accent" "PublicCourseAccent" NOT NULL DEFAULT 'BLUE', ADD COLUMN "symbol" VARCHAR(16) NOT NULL DEFAULT 'A', ADD COLUMN "featured" BOOLEAN NOT NULL DEFAULT false, ADD COLUMN "position" INTEGER NOT NULL DEFAULT 0, ADD COLUMN "hero_variant" VARCHAR(40), ADD COLUMN "image_path" VARCHAR(500), ADD COLUMN "poster_image_path" VARCHAR(500);
ALTER TABLE "public_course_translations" ADD COLUMN "audience" TEXT, ADD COLUMN "comparison_title" VARCHAR(240), ADD COLUMN "duration" VARCHAR(160), ADD COLUMN "focus" TEXT, ADD COLUMN "format_label" VARCHAR(160), ADD COLUMN "image_alt" VARCHAR(500), ADD COLUMN "level" VARCHAR(160), ADD COLUMN "poster_alt" VARCHAR(500), ADD COLUMN "poster_title" VARCHAR(240), ADD COLUMN "prerequisites" TEXT, ADD COLUMN "schedule" VARCHAR(240);
ALTER TABLE "public_events" ADD COLUMN "timeline_status" "PublicEventTimelineStatus" NOT NULL DEFAULT 'UPCOMING', ADD COLUMN "position" INTEGER NOT NULL DEFAULT 0, ADD COLUMN "image_path" VARCHAR(500);
ALTER TABLE "public_event_translations" ADD COLUMN "image_alt" VARCHAR(500), ADD COLUMN "format_label" VARCHAR(160), ADD COLUMN "date_label" VARCHAR(160), ADD COLUMN "time_label" VARCHAR(160), ADD COLUMN "duration_label" VARCHAR(160), ADD COLUMN "location_label" VARCHAR(240), ADD COLUMN "topics" TEXT[] NOT NULL DEFAULT ARRAY[]::TEXT[], ADD COLUMN "overview" TEXT[] NOT NULL DEFAULT ARRAY[]::TEXT[], ADD COLUMN "audience" TEXT[] NOT NULL DEFAULT ARRAY[]::TEXT[], ADD COLUMN "takeaways" TEXT[] NOT NULL DEFAULT ARRAY[]::TEXT[], ADD COLUMN "practical_info" TEXT[] NOT NULL DEFAULT ARRAY[]::TEXT[];
ALTER TABLE "contact_requests" ADD COLUMN "subject" VARCHAR(240), ADD COLUMN "locale" "Language" NOT NULL DEFAULT 'UZ';
ALTER TABLE "exam_registrations" ADD COLUMN "offering_id" UUID, ADD COLUMN "session_id" UUID, ADD COLUMN "current_level" VARCHAR(80), ADD COLUMN "locale" "Language" NOT NULL DEFAULT 'UZ';
ALTER TABLE "event_registrations" ADD COLUMN "participant_count" INTEGER NOT NULL DEFAULT 1, ADD COLUMN "locale" "Language" NOT NULL DEFAULT 'UZ';

CREATE TABLE "public_course_content_items" ("id" UUID NOT NULL, "course_id" UUID NOT NULL, "kind" "PublicCourseContentKind" NOT NULL, "position" INTEGER NOT NULL, CONSTRAINT "public_course_content_items_pkey" PRIMARY KEY ("id"));
CREATE TABLE "public_course_content_translations" ("id" UUID NOT NULL, "item_id" UUID NOT NULL, "language" "Language" NOT NULL, "value" TEXT NOT NULL, CONSTRAINT "public_course_content_translations_pkey" PRIMARY KEY ("id"));
CREATE TABLE "public_course_tracks" ("id" UUID NOT NULL, "course_id" UUID NOT NULL, "position" INTEGER NOT NULL, CONSTRAINT "public_course_tracks_pkey" PRIMARY KEY ("id"));
CREATE TABLE "public_course_track_translations" ("id" UUID NOT NULL, "track_id" UUID NOT NULL, "language" "Language" NOT NULL, "title" VARCHAR(240) NOT NULL, "summary" TEXT NOT NULL, "level" VARCHAR(160) NOT NULL, "highlights" TEXT[] NOT NULL DEFAULT ARRAY[]::TEXT[], CONSTRAINT "public_course_track_translations_pkey" PRIMARY KEY ("id"));
CREATE TABLE "public_event_programme_items" ("id" UUID NOT NULL, "event_id" UUID NOT NULL, "position" INTEGER NOT NULL, "time_label" VARCHAR(40) NOT NULL, CONSTRAINT "public_event_programme_items_pkey" PRIMARY KEY ("id"));
CREATE TABLE "public_event_programme_item_translations" ("id" UUID NOT NULL, "item_id" UUID NOT NULL, "language" "Language" NOT NULL, "title" VARCHAR(240) NOT NULL, "description" TEXT NOT NULL, CONSTRAINT "public_event_programme_item_translations_pkey" PRIMARY KEY ("id"));
CREATE TABLE "public_event_faq_items" ("id" UUID NOT NULL, "event_id" UUID NOT NULL, "position" INTEGER NOT NULL, CONSTRAINT "public_event_faq_items_pkey" PRIMARY KEY ("id"));
CREATE TABLE "public_event_faq_item_translations" ("id" UUID NOT NULL, "item_id" UUID NOT NULL, "language" "Language" NOT NULL, "question" TEXT NOT NULL, "answer" TEXT NOT NULL, CONSTRAINT "public_event_faq_item_translations_pkey" PRIMARY KEY ("id"));
CREATE TABLE "public_faqs" ("id" UUID NOT NULL, "key" VARCHAR(160) NOT NULL, "category" VARCHAR(80) NOT NULL, "position" INTEGER NOT NULL DEFAULT 0, "status" "PublicContentStatus" NOT NULL DEFAULT 'DRAFT', "published_at" TIMESTAMPTZ(3), CONSTRAINT "public_faqs_pkey" PRIMARY KEY ("id"));
CREATE TABLE "public_faq_translations" ("id" UUID NOT NULL, "faq_id" UUID NOT NULL, "language" "Language" NOT NULL, "question" TEXT NOT NULL, "answer" TEXT NOT NULL, CONSTRAINT "public_faq_translations_pkey" PRIMARY KEY ("id"));
CREATE TABLE "public_exam_offerings" ("id" UUID NOT NULL, "key" VARCHAR(80) NOT NULL, "position" INTEGER NOT NULL DEFAULT 0, "status" "PublicContentStatus" NOT NULL DEFAULT 'DRAFT', "published_at" TIMESTAMPTZ(3), CONSTRAINT "public_exam_offerings_pkey" PRIMARY KEY ("id"));
CREATE TABLE "public_exam_offering_translations" ("id" UUID NOT NULL, "offering_id" UUID NOT NULL, "language" "Language" NOT NULL, "title" VARCHAR(160) NOT NULL, "description" TEXT NOT NULL, "format_label" VARCHAR(160) NOT NULL, "duration" VARCHAR(160) NOT NULL, "level" VARCHAR(160) NOT NULL, "highlights" TEXT[] NOT NULL DEFAULT ARRAY[]::TEXT[], CONSTRAINT "public_exam_offering_translations_pkey" PRIMARY KEY ("id"));
CREATE TABLE "public_exam_sessions" ("id" UUID NOT NULL, "offering_id" UUID NOT NULL, "starts_at" TIMESTAMPTZ(3) NOT NULL, "capacity" INTEGER, "active" BOOLEAN NOT NULL DEFAULT true, CONSTRAINT "public_exam_sessions_pkey" PRIMARY KEY ("id"));
CREATE TABLE "public_result_videos" ("id" UUID NOT NULL, "key" VARCHAR(160) NOT NULL, "position" INTEGER NOT NULL DEFAULT 0, "duration" VARCHAR(20) NOT NULL, "poster_path" VARCHAR(500) NOT NULL, "video_path" VARCHAR(500) NOT NULL, "source_creator" VARCHAR(240) NOT NULL, "source_provider" VARCHAR(80) NOT NULL, "source_url" VARCHAR(1000) NOT NULL, "license_url" VARCHAR(1000) NOT NULL, "status" "PublicContentStatus" NOT NULL DEFAULT 'DRAFT', "published_at" TIMESTAMPTZ(3), CONSTRAINT "public_result_videos_pkey" PRIMARY KEY ("id"));
CREATE TABLE "public_result_video_translations" ("id" UUID NOT NULL, "video_id" UUID NOT NULL, "language" "Language" NOT NULL, "title" VARCHAR(240) NOT NULL, CONSTRAINT "public_result_video_translations_pkey" PRIMARY KEY ("id"));
CREATE TABLE "course_registrations" ("id" UUID NOT NULL, "course_id" UUID NOT NULL, "name" VARCHAR(160) NOT NULL, "email" VARCHAR(320), "phone" VARCHAR(32) NOT NULL, "current_level" VARCHAR(80), "message" TEXT, "consent" BOOLEAN NOT NULL, "locale" "Language" NOT NULL DEFAULT 'UZ', "status" "IntakeStatus" NOT NULL DEFAULT 'NEW', "review_note" TEXT, "created_at" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updated_at" TIMESTAMPTZ(3) NOT NULL, CONSTRAINT "course_registrations_pkey" PRIMARY KEY ("id"));

CREATE UNIQUE INDEX "public_course_content_items_course_id_kind_position_key" ON "public_course_content_items"("course_id", "kind", "position");
CREATE UNIQUE INDEX "public_course_content_translations_item_id_language_key" ON "public_course_content_translations"("item_id", "language");
CREATE UNIQUE INDEX "public_course_tracks_course_id_position_key" ON "public_course_tracks"("course_id", "position");
CREATE UNIQUE INDEX "public_course_track_translations_track_id_language_key" ON "public_course_track_translations"("track_id", "language");
CREATE UNIQUE INDEX "public_event_programme_items_event_id_position_key" ON "public_event_programme_items"("event_id", "position");
CREATE UNIQUE INDEX "public_event_programme_item_translations_item_id_language_key" ON "public_event_programme_item_translations"("item_id", "language");
CREATE UNIQUE INDEX "public_event_faq_items_event_id_position_key" ON "public_event_faq_items"("event_id", "position");
CREATE UNIQUE INDEX "public_event_faq_item_translations_item_id_language_key" ON "public_event_faq_item_translations"("item_id", "language");
CREATE UNIQUE INDEX "public_faqs_key_key" ON "public_faqs"("key");
CREATE INDEX "public_faqs_status_position_idx" ON "public_faqs"("status", "position");
CREATE UNIQUE INDEX "public_faq_translations_faq_id_language_key" ON "public_faq_translations"("faq_id", "language");
CREATE UNIQUE INDEX "public_exam_offerings_key_key" ON "public_exam_offerings"("key");
CREATE INDEX "public_exam_offerings_status_position_idx" ON "public_exam_offerings"("status", "position");
CREATE UNIQUE INDEX "public_exam_offering_translations_offering_id_language_key" ON "public_exam_offering_translations"("offering_id", "language");
CREATE UNIQUE INDEX "public_exam_sessions_offering_id_starts_at_key" ON "public_exam_sessions"("offering_id", "starts_at");
CREATE INDEX "public_exam_sessions_active_starts_at_idx" ON "public_exam_sessions"("active", "starts_at");
CREATE UNIQUE INDEX "public_result_videos_key_key" ON "public_result_videos"("key");
CREATE INDEX "public_result_videos_status_position_idx" ON "public_result_videos"("status", "position");
CREATE UNIQUE INDEX "public_result_video_translations_video_id_language_key" ON "public_result_video_translations"("video_id", "language");
CREATE UNIQUE INDEX "course_registrations_course_id_phone_key" ON "course_registrations"("course_id", "phone");
CREATE INDEX "course_registrations_status_created_at_idx" ON "course_registrations"("status", "created_at");
CREATE UNIQUE INDEX "exam_registrations_offering_id_phone_key" ON "exam_registrations"("offering_id", "phone");

ALTER TABLE "public_course_content_items" ADD CONSTRAINT "public_course_content_items_course_id_fkey" FOREIGN KEY ("course_id") REFERENCES "public_courses"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "public_course_content_translations" ADD CONSTRAINT "public_course_content_translations_item_id_fkey" FOREIGN KEY ("item_id") REFERENCES "public_course_content_items"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "public_course_tracks" ADD CONSTRAINT "public_course_tracks_course_id_fkey" FOREIGN KEY ("course_id") REFERENCES "public_courses"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "public_course_track_translations" ADD CONSTRAINT "public_course_track_translations_track_id_fkey" FOREIGN KEY ("track_id") REFERENCES "public_course_tracks"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "public_event_programme_items" ADD CONSTRAINT "public_event_programme_items_event_id_fkey" FOREIGN KEY ("event_id") REFERENCES "public_events"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "public_event_programme_item_translations" ADD CONSTRAINT "public_event_programme_item_translations_item_id_fkey" FOREIGN KEY ("item_id") REFERENCES "public_event_programme_items"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "public_event_faq_items" ADD CONSTRAINT "public_event_faq_items_event_id_fkey" FOREIGN KEY ("event_id") REFERENCES "public_events"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "public_event_faq_item_translations" ADD CONSTRAINT "public_event_faq_item_translations_item_id_fkey" FOREIGN KEY ("item_id") REFERENCES "public_event_faq_items"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "public_faq_translations" ADD CONSTRAINT "public_faq_translations_faq_id_fkey" FOREIGN KEY ("faq_id") REFERENCES "public_faqs"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "public_exam_offering_translations" ADD CONSTRAINT "public_exam_offering_translations_offering_id_fkey" FOREIGN KEY ("offering_id") REFERENCES "public_exam_offerings"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "public_exam_sessions" ADD CONSTRAINT "public_exam_sessions_offering_id_fkey" FOREIGN KEY ("offering_id") REFERENCES "public_exam_offerings"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "public_result_video_translations" ADD CONSTRAINT "public_result_video_translations_video_id_fkey" FOREIGN KEY ("video_id") REFERENCES "public_result_videos"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "course_registrations" ADD CONSTRAINT "course_registrations_course_id_fkey" FOREIGN KEY ("course_id") REFERENCES "public_courses"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "exam_registrations" ADD CONSTRAINT "exam_registrations_offering_id_fkey" FOREIGN KEY ("offering_id") REFERENCES "public_exam_offerings"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "exam_registrations" ADD CONSTRAINT "exam_registrations_session_id_fkey" FOREIGN KEY ("session_id") REFERENCES "public_exam_sessions"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "event_registrations" ADD CONSTRAINT "event_registrations_participant_count_check" CHECK ("participant_count" BETWEEN 1 AND 4);
ALTER TABLE "public_exam_sessions" ADD CONSTRAINT "public_exam_sessions_capacity_check" CHECK ("capacity" IS NULL OR "capacity" > 0);
ALTER TABLE "course_registrations" ADD CONSTRAINT "course_registrations_consent_check" CHECK ("consent" = true);
